package com.kakaplywoods.crm;
import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import java.util.*;
public interface LeadRepository extends JpaRepository<Lead,UUID>{@Query("select l from Lead l where (:status is null or l.status=:status) and (:owner is null or l.assignedTo=:owner) and (:q is null or lower(l.name) like lower(concat('%',:q,'%')) or lower(l.phone) like lower(concat('%',:q,'%')) or lower(l.leadCode) like lower(concat('%',:q,'%')) or lower(coalesce(l.productInterest,'')) like lower(concat('%',:q,'%'))) order by l.createdAt desc")List<Lead> search(@Param("q") String q,@Param("status") String status,@Param("owner") String owner);long countByStatus(String status);}
